import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    k = int(input_data[1])

    if n * (n - 1) < k * n:
        print("-1")
        return

    matches = []
    total_wins_needed = k * n

    if n == 1:
        if k == 0:
            print("0")
        else:
            print("-1")
        return

    for shift in range(k):
        for i in range(n):
            winner = i + 1
            loser = (i + shift + 1) % n + 1
            if winner == loser:
                continue
            matches.append((winner, loser))

    print(len(matches))
    for w, l in matches:
        print(f"{w} {l}")

if __name__ == "__main__":
    solve()
